    $out = '';
    foreach ($groups as $g => $name) {
        if ($n >= $g) { $out .= $bn1000(intdiv($n, $g)) . ' ' . $name . ' '; $n %= $g; }
    }
    if ($n) $out .= $bn1000($n);
    return trim($out);
}
function render_merge($body, $vars) {
    return preg_replace_callback('/\{\{(\w+)\}\}/', function ($m) use ($vars) {
        $k = $m[1];
        return array_key_exists($k, $vars) ? (string)$vars[$k] : $m[0];
    }, $body);
}
