    $lease = $st->fetchColumn();
    if (!$lease) json_out(['ok' => false, 'error' => 'Checklist not found.'], 404);
    $pdo->prepare('DELETE FROM handover_checklists WHERE id=?')->execute([$id]);
    audit($u['name'], 'Handover checklist deleted', 'leases', $lease, $id);
    json_out(['ok' => true]);
}

