    foreach ($tables as $t) {
        try {
            $out['_tables'][$t] = $pdo->query("SELECT * FROM $t")->fetchAll(PDO::FETCH_ASSOC);
        } catch (Exception $e) { $out['_tables'][$t] = []; }
