    json_out($out);
}

case 'app-audit': {
    /* superadmin only — audit trail with pagination */
    $u = require_user();
    if ($u['role'] !== 'superadmin' && $u['email'] !== ADMIN_EMAIL) json_out(['ok' => false, 'error' => 'Super admin only.'], 403);
    $limit = min(200, max(1, (int)($body['limit'] ?? 50)));
