    $rows = db()->query("SELECT ts,user,action,module,entity,details FROM audit_log ORDER BY id DESC LIMIT $limit OFFSET $offset")->fetchAll(PDO::FETCH_ASSOC);
    $total = (int)db()->query('SELECT COUNT(*) FROM audit_log')->fetchColumn();
