        if (!$tid) json_out(['ok' => false, 'error' => 't (tenant id) required for staff.'], 400);
        $st = $pdo->prepare('SELECT COUNT(*) FROM tenants WHERE id=?'); $st->execute([$tid]);
        if (!$st->fetchColumn()) json_out(['ok' => false, 'error' => 'Tenant not found.'], 404);
    } else {
