            'tenant' => ['id' => $t['id'], 'name' => $t['name'], 'kind' => $t['kind'], 'nrb' => (int)$t['nrb']],
            'score' => $sc['score'], 'band' => $sc['band'], 'band_color' => $sc['band_color'],
            'factors' => $sc['factors'],
        ];
