            $stat = ['Planning' => 0, 'In_Progress' => 0, 'On_Hold' => 0, 'Completed' => 0, 'Cancelled' => 0];
            foreach ($rows as $p) $stat[$p['status']] = ($stat[$p['status']] ?? 0) + 1;
